    // 3836dee-TC-003 - Add a pricing tier to an existing fee configuration
    @Test
    public void addPricingTierToExistingFeeConfiguration() {
        // Precondition: Create a tiered fee configuration first
        String createFeeBody = """
            {
              "merchantCategoryCode": "5411",
              "capabilityCode": "ONLINE_PAYMENT",
              "feeType": "TIERED",
              "effectiveFrom": "2026-01-01"
            }
            """;
        String feeId = given().contentType(ContentType.JSON).body(createFeeBody).when().post("/api/v1/fees").then().statusCode(201).extract().path("data.id");
        Assert.assertNotNull(feeId, "Precondition failed: Fee configuration creation returned null ID");
        String addTierBody = """
            {
              "tierFrom": 0.00,
              "tierTo": 1000.00,
              "rate": 2.50,
              "flatAmount": 0.00
            }
            """;
        Response tierResponse = given().contentType(ContentType.JSON).body(addTierBody).when().post("/api/v1/fees/{id}/tiers", feeId).then().statusCode(201).body("success", equalTo(true)).body("data.id", notNullValue()).extract().response();
        Number tierFrom = tierResponse.path("data.tierFrom");
        Number tierTo = tierResponse.path("data.tierTo");
        Number rate = tierResponse.path("data.rate");
        Assert.assertNotNull(tierFrom, "tierFrom should not be null");
        Assert.assertEquals(tierFrom.doubleValue(), 0.00, 0.001);
        Assert.assertNotNull(tierTo, "tierTo should not be null");
        Assert.assertEquals(tierTo.doubleValue(), 1000.00, 0.001);
        Assert.assertNotNull(rate, "rate should not be null");
        Assert.assertEquals(rate.doubleValue(), 2.50, 0.001);
    }

    // 3836dee-TC-004 - Assign a payment capability to an existing merchant
