    // 3836dee-TC-024
    @Test
    public void rejectTerminalRegistrationWhenSerialNumberIsAlreadyRegistered() {
        long timestamp = System.currentTimeMillis();
        String createMerchantBody = """
                        {
                          "legalName": "Merchant %d",
                          "tradeName": "Trade %d",
                          "registrationNo": "REG-%d",
                          "businessType": "CORPORATION",
              "userId": %d
            }
            """.formatted(timestamp, timestamp, timestamp, System.currentTimeMillis() % 100_000);
        Response merchantResp = given().contentType(ContentType.JSON).body(createMerchantBody).when().post("/api/v1/merchants").then().statusCode(anyOf(is(200), is(201))).extract().response();
        String merchantId = merchantResp.path("data.id") != null ? merchantResp.path("data.id") : merchantResp.path("id");
        Assert.assertNotNull(merchantId, "Precondition failed: Merchant ID creation returned null");
        String createStoreBody = """
            {
              "name": "Store %d"
            }
            """.formatted(timestamp);
        Response storeResp = given().contentType(ContentType.JSON).body(createStoreBody).when().post("/api/v1/merchants/{merchantId}/stores", merchantId).then().statusCode(anyOf(is(200), is(201))).extract().response();
        String storeId = storeResp.path("data.id") != null ? storeResp.path("data.id") : storeResp.path("id");
        Assert.assertNotNull(storeId, "Precondition failed: Store ID creation returned null");
        String duplicateSerial = "SN-DUP-" + timestamp;
        String firstTerminalBody = """
            {
              "merchantId": "%s",
              "storeId": "%s",
              "serialNumber": "%s",
              "model": "A920 Pro",
              "manufacturer": "PAX Technology"
            }
            """.formatted(merchantId, storeId, duplicateSerial);
        given().contentType(ContentType.JSON).body(firstTerminalBody).when().post("/api/v1/terminals").then().statusCode(anyOf(is(200), is(201)));
        given().contentType(ContentType.JSON).body(firstTerminalBody).when().post("/api/v1/terminals").then().statusCode(anyOf(is(400), is(409)));
    }

